"""Search radius-two balls generated by mixed exact unit directions.

Every point is an exact sum of at most two generators from
U union rho*U union ... union rho**(layers-1)*U, where U is Haugland's
84-direction set. Edge acceptance uses exact norm equality. A SAT model
rejects the exported candidate; a timeout preserves UNKNOWN.
"""

from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
import itertools
import json
from pathlib import Path
import time

from .construct import spindle_rotation, unit_directions
from .field import ZERO, ONE
from .search import export
from .solve import solve


def mixed_directions(layers):
    if not 1 <= layers <= 3:
        raise ValueError("Supported layer counts are 1, 2, and 3")
    rho = spindle_rotation()
    rotation = ONE
    generators = set()
    for _ in range(layers):
        generators.update(rotation * u for u in unit_directions())
        rotation *= rho
    generators = tuple(sorted(generators,
                              key=lambda z: (z.denominator, z.coefficients)))
    if not all(u.is_unit() for u in generators):
        raise ArithmeticError("A mixed generator does not have exact norm one")
    return generators


def radius_two_points(generators, max_vertices=40000):
    points = {ZERO, *generators}
    for u, v in itertools.combinations_with_replacement(generators, 2):
        points.add(u + v)
        if len(points) > max_vertices:
            raise ValueError(f"Vertex cap exceeded: {max_vertices}")
    return tuple(sorted(points, key=lambda z: (z.denominator, z.coefficients)))


def run(layers, out, timeout=60, max_vertices=40000):
    out = Path(out)
    out.mkdir(parents=True, exist_ok=False)
    timeout = min(float(timeout), 60.0)
    if timeout <= 0:
        raise ValueError("Solver timeout must be positive")
    started = time.monotonic()
    metadata = {
        "family": "mixed-exact-direction-ball",
        "radius": 2,
        "layers": layers,
        "generator_rule": "union(rho**j * U84 for j in range(layers))",
        "rotation": "rho=(7+i*sqrt(15))/8",
        "max_vertices": max_vertices,
        "solver_timeout_seconds": timeout,
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "success_certificate": False,
        "program_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    }
    (out / "configuration.json").write_text(json.dumps(metadata, indent=2) + "\n")
    generators = mixed_directions(layers)
    points = radius_two_points(generators, max_vertices)
    metadata.update({"unit_generator_count": len(generators),
                     "point_generation_seconds": time.monotonic() - started})
    print(json.dumps({"stage": "points_generated", **metadata,
                      "vertices": len(points)}), flush=True)
    graph = export(points, out / "graph.json", metadata)
    results = {}
    for k in (6, 5):
        results[str(k)] = solve(out / "graph.json", k, out / f"color-{k}", timeout)
    summary = {
        "schema": "hn-ball-search-v1",
        "layers": layers,
        "unit_generator_count": len(generators),
        "vertices": len(graph["vertices"]),
        "edges": len(graph["edges"]),
        "elapsed_seconds": time.monotonic() - started,
        "coloring_status": {k: v["status"] for k, v in results.items()},
        "success_certificate": False,
    }
    (out / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    print(json.dumps(summary), flush=True)
    return summary


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--layers", type=int, choices=(1, 2, 3), required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--timeout", type=float, default=60)
    parser.add_argument("--max-vertices", type=int, default=40000)
    args = parser.parse_args()
    run(args.layers, args.out, args.timeout, args.max_vertices)


if __name__ == "__main__":
    main()
